function createFeather(beginX, beginY, angle, lFeather)
{

  //let PARAMETERS//

  //transitions
  let lCalamus = 50;  //length of the calamus (begin of the feather without barbs
  let tip = 10;  //length of the tip (diference between the end of the barbs and the end of the hachis)

  let bAfterfeathers = 0.15;  //begin of the afterfeathers (begin of the barbs)
  let bVane = 0.3;  //begin of the vane (end fo the afterfeathers and begin of the organized barbs)

  //curvature of the feather
  let deltaCP1y = random(-50, 50);
  let deltaCP2y = random(-50, 50);

  let deltaBP1y = random(40, 80);
  let deltaBP2y = random(50, 90);

  let deltaTP1y = random(40, 80);
  let deltaTP2y = random(50, 90);

  //colors of the feather
  let h1= random(360);  //main hue
  let h2 = random(360);  //second hue
  let colorChange = random(bVane, 0.75);  //point where the hue start to change



  //let DRAWING//

  feather.beginDraw();
  feather.colorMode(HSB, 360, 100, 100);
  feather.noFill();
  feather.smooth();
  feather.background(0, 0);
  feather.translate(beginX, beginY);
  feather.rotate(-angle);

  shadow.beginDraw();
  shadow.noFill();
  shadow.stroke(220);
  shadow.background(0, 0);
  shadow.translate(beginX, beginY);
  shadow.rotate(-angle);


  //let THE let OF let FEATHER//
  //center
  let cBegin  =  new  PVector  (  0,        0          );
  let cP1     =  new  PVector  (  0,        deltaCP1y  );
  let cP2     =  new  PVector  (  lFeather, deltaCP2y  );
  let cEnd    =  new  PVector  (  lFeather, 0          );
  //bezier(cBegin.x, cBegin.y,  cP1.x, cP1.y,   cP2.x, cP2.y,   cEnd.x, cEnd.y);


  //bottom
  let bBegin  =  new PVector  (  cBegin.x + lCalamus,   cBegin.y           );
  let bP1     =  new PVector  (  cP1.x + lCalamus,      cP1.y + deltaBP1y  );
  let bP2     =  new PVector  (  cP2.x + tip,           cP2.y + deltaBP2y  );
  let bEnd    =  new PVector  (  cEnd.x + tip,          cEnd.y             );   
  //bezier(bBegin.x, bBegin.y, bP1.x, bP1.y,   bP2.x, bP2.y,   bEnd.x, bEnd.y);


  //top
  let tBegin  =  new PVector  (  cBegin.x + lCalamus,   cBegin.y           );
  let tP1     =  new PVector  (  cP1.x + lCalamus,      cP1.y - deltaTP1y  );
  let tP2     =  new PVector  (  cP2.x + tip,           cP2.y - deltaTP2y  );
  let tEnd    =  new PVector  (  cEnd.x + tip,          cEnd.y             );
  //bezier(tBegin.x, tBegin.y,  tP1.x, tP1.y,   tP2.x, tP2.y,   tEnd.x, tEnd.y);




  //let THE BARBS//

  //initialize the variables that modify the barbs
  let deltaBX = 0, deltaTX = 0;
  let deltaBY = 0, deltaTY = 0;

  for (let i = bAfterfeathers; i < 1; i += 0.001)
  {
    //define the points
    let cx = bezierPoint(cBegin.x, cP1.x, cP2.x, cEnd.x, i);
    let cy = bezierPoint(cBegin.y, cP1.y, cP2.y, cEnd.y, i);
    let bx = bezierPoint(bBegin.x, bP1.x, bP2.x, bEnd.x, i);
    let by = bezierPoint(bBegin.y, bP1.y, bP2.y, bEnd.y, i);
    let tx = bezierPoint(tBegin.x, tP1.x, tP2.x, tEnd.x, i);
    let ty = bezierPoint(tBegin.y, tP1.y, tP2.y, tEnd.y, i);


    //define the direction of the barbs
    let rdm = lerp(0.92, 1, i);  //more probable to change the direction at the beggining
    let maxDeltaX = lerp(25, 0, i);  //maximum change is bigger at the beggining 
    if (random(1) > rdm) deltaBX = random(-maxDeltaX, maxDeltaX);  //set the modifier for the bottom part
    if (random(1) > rdm) deltaTX = random(-maxDeltaX, maxDeltaX);  //set the modifier for the top part


    //define the fuzzines at the afterfeather
    let fuzz = i;
    if (fuzz > 0.3) {fuzz = 0;}  //definite barbs at the end
    else {fuzz = map(fuzz, 0, 0.5, 1, 0);}  //fuzzy barbs at the beggining
    let fuzziness = random(20, 40);  //set de maximum fuzziness
    deltaBY = fuzz*random(-fuzziness, fuzziness);  //set the modifier for the bottom part
    deltaTY = fuzz*random(-fuzziness, fuzziness);  //set the modifier for the top part


    //set the color
    if (i < bVane)  //lighter colors at the beggining
    {
      let k = map(i, bAfterfeathers, bVane, 0, 1);
      feather.stroke(h1, lerp(1, 100, k), 95, 60);  //set saturation
    }
    else if (i < colorChange)  //main color
    {
      feather.stroke(h1, 100, 95, 60);
    }
    else  //gradually change to the second color 
    { 
      let color1 = color(h1, 100, 95);
      let color2 = color(h2, 75, 50);
      let j = map(i, colorChange, 1, 0, 1);
      feather.stroke(lerpColor(color1,color2,j), 60);  
    }


    //draw the barbs
    feather.strokeWeight(2);
    feather.bezier(cx, cy,   (cx+bx)/2, cy,   (cx+bx)/2, by,   bx + deltaBX, by + deltaBY);
    feather.bezier(cx, cy,   (cx+tx)/2, cy,   (cx+tx)/2, ty,   tx + deltaTX, ty + deltaTY);

    //draw the shadow of the barbs
    shadow.strokeWeight(2);
    shadow.bezier(cx, cy,   (cx+bx)/2, cy,   (cx+bx)/2, by,   bx + deltaBX, by + deltaBY);
    shadow.bezier(cx, cy,   (cx+tx)/2, cy,   (cx+tx)/2, ty,   tx + deltaTX, ty + deltaTY);


  }



  //let THE HACHIS//

  let oldcx = bezierPoint(cBegin.x, cP1.x, cP2.x, cEnd.x, 0);
  let oldcy = bezierPoint(cBegin.y, cP1.y, cP2.y, cEnd.y, 0);

  for (let i = 0; i < 0.75; i += 0.001)
  {
    //initialize the second point
    let cx = bezierPoint(cBegin.x, cP1.x, cP2.x, cEnd.x, i);
    let cy = bezierPoint(cBegin.y, cP1.y, cP2.y, cEnd.y, i);

    //draw the hachis
    feather.stroke(h1, 10, 90, 70);  //set let feather.strokeWeight(map(i, 0, 0.75, 6, 0));  //set the strokeWeight
    feather.line(oldcx, oldcy, cx, cy);  //draw the line

    //draw the shadow of the hachis
    shadow.strokeWeight(map(i, 0, 0.75, 6, 0));  //set the strokeWeight
    shadow.line(oldcx, oldcy, cx, cy);  //draw the line


    oldcx = cx;
    oldcy = cy;
  }



  //let DRAWING//

  feather.resetMatrix();
  feather.endDraw();

  shadow.resetMatrix();
  shadow.endDraw();

}



// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
